begin;
insert into auth.users(id,email,raw_user_meta_data) select ('20000000-0000-4000-8000-00000000000'||n)::uuid,'shop-test-'||n||'@example.invalid','{"full_name":"Shop test","requested_role":"membre","motivation":"Temporary shop security fixture","city":"Yaoundé","region":"Centre","phone":"+237600000000"}'::jsonb from generate_series(1,5) n;
update public.profiles set status='approved',role=case right(id::text,1) when '1' then 'membre' when '2' then 'admin' when '3' then 'super_admin' when '4' then 'benevole' else 'volontaire' end where id::text like '20000000-0000-4000-8000-%';
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000004',true);
set local role authenticated;
do $$begin begin perform public.shop_action('request_activation','{"motivation":"Je fabrique des produits recyclés"}');raise exception 'FAILED volunteer allowed';exception when insufficient_privilege then null;end;end$$;
reset role;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000005',true);
set local role authenticated;
do $$begin begin perform public.shop_action('request_activation','{"motivation":"Je fabrique des produits recyclés"}');raise exception 'FAILED voluntary allowed';exception when insufficient_privilege then null;end;end$$;
reset role;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select public.shop_action('request_activation','{"motivation":"Je fabrique des produits recyclés"}');
do $$begin begin update public.shop_sellers set status='approved';raise exception 'FAILED self activation';exception when insufficient_privilege then null;end;begin perform public.shop_action('create_product','{}');raise exception 'FAILED unactivated publication';exception when insufficient_privilege then null;end;end$$;
reset role;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
set local role authenticated;
do $$begin begin perform public.shop_action('review_seller','{"id":"20000000-0000-4000-8000-000000000001","status":"approved"}');raise exception 'FAILED admin activation';exception when insufficient_privilege then null;end;end$$;
reset role;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000003',true);
set local role authenticated;
select public.shop_action('review_seller','{"id":"20000000-0000-4000-8000-000000000001","status":"approved"}');
reset role;
insert into storage.objects(bucket_id,name) values('shop-photos','20000000-0000-4000-8000-000000000001/test.webp'),('shop-photos','20000000-0000-4000-8000-000000000002/test.webp');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select public.shop_action('create_product','{"title":"Produit test","description":"Description de test du produit","category":"Accessoires","price":8000,"delivery":2000,"delivery_zone":"Yaoundé","stock":2,"photo_path":"20000000-0000-4000-8000-000000000001/test.webp","status":"published","association_product":true}');
do $$begin if not exists(select 1 from public.shop_products where owner_id=auth.uid() and status='pending' and not association_product) then raise exception 'FAILED client privilege spoof';end if;begin update public.shop_products set status='published';raise exception 'FAILED direct publication';exception when insufficient_privilege then null;end;end$$;
reset role;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select public.shop_action('review_product',jsonb_build_object('id',(select id from public.shop_products where owner_id='20000000-0000-4000-8000-000000000001'),'status','published'));
select public.shop_action('create_product','{"title":"Association test","description":"Description de test association","category":"Accessoires","price":8000,"delivery":2000,"delivery_zone":"Yaoundé","stock":2,"photo_path":"20000000-0000-4000-8000-000000000002/test.webp","association_product":false}');
do $$begin if not exists(select 1 from public.shop_products where owner_id=auth.uid() and status='published' and association_product) then raise exception 'FAILED association publication';end if;end$$;
reset role;
select set_config('request.jwt.claim.sub','',true);
set local role anon;
do $$begin if not exists(select 1 from public.shop_products where title='Produit test') then raise exception 'FAILED public catalog';end if;begin perform public.shop_action('review_product','{}');raise exception 'FAILED anonymous operation';exception when insufficient_privilege then null;end;end$$;
reset role;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000003',true);
set local role authenticated;
select public.shop_action('review_seller','{"id":"20000000-0000-4000-8000-000000000001","status":"suspended"}');
reset role;
select set_config('request.jwt.claim.sub','',true);
set local role anon;
do $$begin if exists(select 1 from public.shop_products where title='Produit test') then raise exception 'FAILED suspended seller visible';end if;end$$;
reset role;
rollback;
